#!/usr/bin/env python3
"""Regenerate the engineering and semester exercise inventory."""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
lessons = sorted(p for semester in ("S1", "S2") for p in (ROOT / "lessons" / semester).glob("[0-9][0-9][0-9]-*"))
lesson_files = [p for d in lessons for p in (d / "code").rglob("*") if p.is_file()]
challenges = [p for d in lessons for p in (d / "code").glob("challenge.*") if p.is_file()]
go_tests = [p for d in lessons for p in (d / "code").rglob("*_test.go")]

lines = [
    "# Code artifact inventory", "",
    "Generated by `python tools/generate_code_inventory.py`.", "",
    f"- Numbered engineering lessons: {len(lessons)}",
    f"- Files under numbered lesson `code/` directories: {len(lesson_files)}",
    f"- Distinct `challenge.*` source files: {len(challenges)}",
    f"- Go test files in numbered lessons: {len(go_tests)}",
    f"- Skipped Go tests: {sum('t.Skip' in p.read_text(errors='ignore') for p in go_tests)}", "",
    "## Engineering workspaces", "",
    "| Lesson | Files | Representative source files |", "|---:|---:|---|",
]
for lesson in lessons:
    files = sorted(p for p in (lesson / "code").rglob("*") if p.is_file())
    sources = [p.name for p in files if p.suffix.lower() in {".c", ".go", ".rs", ".sql"}]
    lines.append(f"| {lesson.name[:3]} | {len(files)} | {', '.join(sources[:6]) or 'see code folder'} |")

lines += ["", "## Semester exercises inside `lessons/`", "", "| Semester | Course files | Python tests |", "|---|---:|---:|"]
for semester in ("S1", "S2"):
    folder = ROOT / "lessons" / semester
    courses = [p for p in folder.glob("*.py") if not p.name.startswith("test_")]
    tests = list(folder.glob("test_*.py"))
    lines.append(f"| {semester} | {len(courses)} | {len(tests)} |")

(ROOT / "CODE-INVENTORY.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
print(f"wrote inventory: {len(lesson_files)} engineering files, 21 semester exercise files")
